import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Devis = () => {
  const [devis, setDevis] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [lignes, setLignes] = useState([{ produit_id: '', quantite: 1 }]);
  const [formData, setFormData] = useState({ taux_tva: 21, notes: '' });
  const [totaux, setTotaux] = useState({ htva: 0, tva: 0, tvac: 0 });

  const user = JSON.parse(localStorage.getItem('user') || '{}');
  const token = localStorage.getItem('token');
  const config = { headers: { Authorization: `Bearer ${token}` } };
  const isAdmin = user.role === 'admin';

  const produits = [
    { id: 1, nom: 'Panneau Solaire Monocristallin 305W', prix: 224.95 },
    { id: 2, nom: 'Aiko 445Wp Lichtgewicht', prix: 139.63 },
    { id: 3, nom: 'Panneau Solaire Polycristallin 270W', prix: 164.95 },
    { id: 4, nom: 'Onduleur Phoenix 12V/500W', prix: 189.00 },
    { id: 5, nom: 'Batterie Lithium 12.8V 200Ah', prix: 1299.00 }
  ];

  useEffect(() => { fetchDevis(); }, []);
  useEffect(() => { calculerTotaux(); }, [lignes, formData.taux_tva]);

  const calculerTotaux = () => {
    const htva = lignes.reduce((sum, l) => {
      const p = produits.find(x => x.id === parseInt(l.produit_id));
      return sum + (parseFloat(l.quantite || 0) * (p?.prix || 0));
    }, 0);
    const tva = htva * (parseFloat(formData.taux_tva) / 100);
    setTotaux({ htva: htva.toFixed(2), tva: tva.toFixed(2), tvac: (htva + tva).toFixed(2) });
  };

  const fetchDevis = async () => {
    try {
      const res = await axios.get('http://192.168.129.16:8000/api/devis', config);
      let data = res.data.data || [];
      if (!isAdmin) data = data.filter(d => d.Client?.email === user.email);
      setDevis(data);
    } catch (err) { console.error(err); }
  };

  const updateLigne = (i, field, val) => {
    const newL = [...lignes];
    newL[i][field] = val;
    setLignes(newL);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (lignes.every(l => !l.produit_id)) return alert('Ajoutez au moins un produit');
    try {
      const response = await axios.post('http://192.168.129.16:8000/api/devis', {
        ...formData,
        lignes: lignes.filter(l => l.produit_id).map(l => {
          const p = produits.find(x => x.id === parseInt(l.produit_id));
          return { description_personnalisee: p?.nom, prix_unitaire: p?.prix, quantite: l.quantite };
        }),
        montant_ht: totaux.htva, montant_tva: totaux.tva, montant_ttc: totaux.tvac
      }, config);
      if (response.data.success) {
        alert('Demande envoyee !');
        setShowForm(false);
        setLignes([{ produit_id: '', quantite: 1 }]);
        fetchDevis();
      }
    } catch (err) { alert('Erreur: ' + (err.response?.data?.message || err.message)); }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Supprimer ?')) {
      await axios.delete(`http://192.168.129.16:8000/api/devis/${id}`, config);
      fetchDevis();
    }
  };

  const updateStatut = async (id, statut) => {
    await axios.patch(`http://192.168.129.16:8000/api/devis/${id}/statut`, { statut }, config);
    fetchDevis();
  };

  const convertir = async (id) => {
    if (window.confirm('Convertir en facture ?')) {
      await axios.post(`http://192.168.129.16:8000/api/devis/${id}/convertir-facture`, {}, config);
      alert('Facture creee et email envoye !');
      fetchDevis();
    }
  };

  const getStatut = (s) => {
    const colors = { brouillon: '#ff9800', envoye: '#2196f3', accepte: '#4caf50', refuse: '#f44336' };
    const labels = { brouillon: 'En attente', envoye: 'Envoye', accepte: 'Accepte', refuse: 'Refuse' };
    return <span style={{ background: colors[s] || '#999', color: '#fff', padding: '4px 10px', borderRadius: '15px', fontSize: '11px' }}>{labels[s] || s}</span>;
  };

  return (
    <div style={{ minHeight: '100vh', background: '#f5f7fb' }}>
      <div style={{ background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', padding: '15px 20px', color: 'white' }}>
        <div style={{ maxWidth: '1200px', margin: '0 auto', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '10px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <span style={{ fontSize: '32px' }}>☀️</span>
            <div>
              <h1 style={{ margin: 0, fontSize: '18px' }}>Anneessens & Co</h1>
              <p style={{ margin: 0, fontSize: '11px', opacity: 0.9 }}>Solutions Panneaux Solaires</p>
            </div>
          </div>
          <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
            <button onClick={() => window.location.href = '/dashboard'} style={{ padding: '8px 15px', background: 'rgba(255,255,255,0.2)', color: 'white', border: '1px solid rgba(255,255,255,0.3)', borderRadius: '6px', cursor: 'pointer', fontSize: '13px' }}>← Retour</button>
            {!isAdmin && <button onClick={() => setShowForm(true)} style={{ padding: '8px 15px', background: 'white', color: '#667eea', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>+ Demande</button>}
          </div>
        </div>
      </div>

      <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '15px' }}>
        <h1 style={{ margin: '0 0 5px 0', fontSize: '1.4rem' }}>{isAdmin ? '📄 Gestion des Devis' : '📄 Mes Demandes'}</h1>
        <p style={{ margin: '0 0 15px 0', color: '#666', fontSize: '0.9rem' }}>{isAdmin ? 'Validez ou refusez les demandes' : 'Creez et suivez vos demandes'}</p>

        {showForm && !isAdmin && (
          <div style={{ background: '#fff', padding: '20px', borderRadius: '10px', marginBottom: '15px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
            <h2 style={{ color: '#667eea', margin: '0 0 15px 0', fontSize: '1.1rem' }}>📝 Nouvelle Demande</h2>
            <div style={{ background: '#f0f7ff', padding: '12px', borderRadius: '6px', marginBottom: '15px', fontSize: '0.9rem' }}><strong>Client:</strong> {user.prenom} {user.nom} - {user.email}</div>
            <form onSubmit={handleSubmit}>
              <div style={{ overflowX: 'auto', marginBottom: '15px' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: '400px' }}>
                  <thead>
                    <tr>
                      <th style={{ background: '#667eea', color: '#fff', padding: '10px 8px', textAlign: 'left', fontSize: '0.85rem' }}>Produit</th>
                      <th style={{ background: '#667eea', color: '#fff', padding: '10px 8px', textAlign: 'right', width: '70px', fontSize: '0.85rem' }}>Prix</th>
                      <th style={{ background: '#667eea', color: '#fff', padding: '10px 8px', textAlign: 'center', width: '60px', fontSize: '0.85rem' }}>Qte</th>
                      <th style={{ background: '#667eea', color: '#fff', padding: '10px 8px', textAlign: 'right', width: '70px', fontSize: '0.85rem' }}>Total</th>
                      <th style={{ background: '#667eea', color: '#fff', padding: '10px 8px', width: '40px' }}></th>
                    </tr>
                  </thead>
                  <tbody>
                    {lignes.map((l, i) => {
                      const p = produits.find(x => x.id === parseInt(l.produit_id));
                      return (
                        <tr key={i}>
                          <td style={{ padding: '10px 8px', borderBottom: '1px solid #eee', fontSize: '0.85rem' }}>
                            <select value={l.produit_id} onChange={e => updateLigne(i, 'produit_id', e.target.value)} style={{ width: '100%', padding: '8px', border: '1px solid #ddd', borderRadius: '5px', fontSize: '0.85rem' }}>
                              <option value="">-- Choisir --</option>
                              {produits.map(pr => <option key={pr.id} value={pr.id}>{pr.nom}</option>)}
                            </select>
                          </td>
                          <td style={{ padding: '10px 8px', borderBottom: '1px solid #eee', fontSize: '0.85rem', textAlign: 'right' }}>{p ? p.prix.toFixed(2) : '-'}</td>
                          <td style={{ padding: '10px 8px', borderBottom: '1px solid #eee', fontSize: '0.85rem', textAlign: 'center' }}>
                            <input type="number" min="1" value={l.quantite} onChange={e => updateLigne(i, 'quantite', e.target.value)} style={{ width: '50px', padding: '8px', border: '1px solid #ddd', borderRadius: '5px', textAlign: 'center', fontSize: '0.85rem' }} />
                          </td>
                          <td style={{ padding: '10px 8px', borderBottom: '1px solid #eee', fontSize: '0.85rem', textAlign: 'right', fontWeight: 'bold' }}>{p ? (p.prix * l.quantite).toFixed(2) : '-'}</td>
                          <td style={{ padding: '10px 8px', borderBottom: '1px solid #eee' }}>{lignes.length > 1 && <button type="button" onClick={() => setLignes(lignes.filter((_, j) => j !== i))} style={{ padding: '5px 10px', background: '#f44336', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '0.8rem' }}>×</button>}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
              <button type="button" onClick={() => setLignes([...lignes, { produit_id: '', quantite: 1 }])} style={{ padding: '8px 15px', background: '#667eea', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '0.85rem' }}>+ Ajouter</button>
              <div style={{ background: '#f8f9fa', padding: '15px', borderRadius: '8px', marginTop: '15px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', padding: '5px 0', fontSize: '0.9rem' }}><span>HTVA:</span><span>{totaux.htva} EUR</span></div>
                <div style={{ display: 'flex', justifyContent: 'space-between', padding: '5px 0', fontSize: '0.9rem' }}><span>TVA 21%:</span><span>{totaux.tva} EUR</span></div>
                <div style={{ display: 'flex', justifyContent: 'space-between', padding: '10px 0', fontSize: '1.1rem', fontWeight: 'bold', borderTop: '2px solid #667eea', marginTop: '5px' }}><span>TVAC:</span><span>{totaux.tvac} EUR</span></div>
              </div>
              <div style={{ display: 'flex', gap: '10px', marginTop: '15px', flexWrap: 'wrap' }}>
                <button type="submit" style={{ padding: '12px 25px', background: '#4caf50', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', flex: '1', minWidth: '120px' }}>Envoyer</button>
                <button type="button" onClick={() => setShowForm(false)} style={{ padding: '12px 25px', background: '#f44336', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', flex: '1', minWidth: '120px' }}>Annuler</button>
              </div>
            </form>
          </div>
        )}

        {devis.map(d => (
          <div key={d.id_devis} style={{ background: 'white', borderRadius: '10px', padding: '15px', marginBottom: '12px', boxShadow: '0 2px 6px rgba(0,0,0,0.08)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: '10px', marginBottom: '10px' }}>
              <div>
                <div style={{ fontWeight: 'bold', color: '#667eea', fontSize: '1rem' }}>{d.numero_devis}</div>
                <div style={{ color: '#666', fontSize: '0.85rem' }}>{d.Client?.nom} {d.Client?.prenom}</div>
              </div>
              {getStatut(d.statut)}
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px', marginBottom: '10px', fontSize: '0.85rem' }}>
              <span>📅 {new Date(d.date_creation).toLocaleDateString('fr-FR')}</span>
              <span>💰 {parseFloat(d.montant_ttc || 0).toFixed(2)} EUR</span>
            </div>
            {isAdmin && (
              <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                <select value={d.statut} onChange={e => updateStatut(d.id_devis, e.target.value)} style={{ padding: '8px', border: '1px solid #ddd', borderRadius: '5px', fontSize: '0.85rem' }}>
                  <option value="brouillon">En attente</option>
                  <option value="accepte">Accepte</option>
                  <option value="refuse">Refuse</option>
                </select>
                {d.statut === 'accepte' && <button onClick={() => convertir(d.id_devis)} style={{ padding: '6px 12px', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '0.8rem', background: '#4caf50', color: 'white' }}>Facture</button>}
                <button onClick={() => handleDelete(d.id_devis)} style={{ padding: '6px 12px', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '0.8rem', background: '#f44336', color: 'white' }}>Suppr</button>
              </div>
            )}
          </div>
        ))}

        {devis.length === 0 && <div style={{ background: '#fff', padding: '20px', borderRadius: '10px', textAlign: 'center', color: '#999' }}>Aucun devis</div>}
      </div>
    </div>
  );
};

export default Devis;
